import test from 'node:test';import assert from 'node:assert/strict';
import {Armory,rollItem,fitPosition,rng,hash32,GRID_SIZES} from '../src/armory.mjs';
import {EQUIPMENT_BASES,UNIQUES,SETS,REGIONS,ENEMIES,RARITIES,EQUIP_SLOTS} from '../src/catalog.mjs';
const make=(x={})=>new Armory({seed:'test',level:45,seedStarter:false,...x});
const item=(id,opts={})=>({...rollItem({seed:'test',eventId:id,level:10,...opts}),id});
const few=arr=>arr.map(x=>x.id);
test('catalog spans every equipment slot including paired rings',()=>{let game=make();assert.equal(EQUIP_SLOTS.length,13);for(const x of EQUIP_SLOTS)assert.ok(EQUIPMENT_BASES.some(b=>b.slot===(x.startsWith('ring')?'ring':x)));assert.ok(EQUIPMENT_BASES.length>=45);assert.ok(UNIQUES.length>=10)});
test('rarity names and each base produce distinct item power',()=>{for(const rarity of RARITIES){const a=rollItem({seed:'x',forceRarity:rarity,eventId:'x',level:20});assert.equal(a.rarity,rarity);assert.ok(a.itemPower>0);assert.ok(Object.values(a.stats).every(x=>Number.isFinite(x)&&x>=0))}});
test('deterministic draw across seeds and events',()=>{const args={seed:'alpha',eventId:'e-4',serial:1,region:'clay',level:30};assert.deepEqual(rollItem(args),rollItem(args));assert.notDeepEqual(rollItem(args),rollItem({...args,serial:2}));assert.equal(rng('s')(),rng('s')())});
test('all regions generate ecological elemental affixes',()=>{for(const r of REGIONS){const a=rollItem({seed:'x',eventId:r.id,region:r.id,level:11,forceRarity:'rare'});assert.equal(a.region,r.id);assert.ok(Object.keys(a.stats).includes(r.element));}});
test('unique item skill strings persist, unique event id and finite stats',()=>{for(const u of UNIQUES){const a=rollItem({seed:'x',eventId:u.id,forceRarity:'legendary',forceSlot:u.slot,forceUnique:u.id});assert.equal(a.unique,u.id);assert.equal(a.effect,u.effect);assert.ok(a.effectText&&a.lore);assert.deepEqual(a.stats,structuredClone(a.stats))}});
test('grid pack never overlaps and handles non-square equipment',()=>{const g=make();const a=item('a',{forceSlot:'mainhand'}),b=item('b',{forceSlot:'chest'});assert.equal(g.grantItem(a).container,'bag');assert.equal(g.grantItem(b).container,'bag');const ps=g.state.placements;assert.equal(ps.length,2);assert.ok(ps[0].x+ps[0].item.w<=10);assert.ok(ps[1].y+ps[1].item.h<=6);assert.equal(fitPosition([ps[0]],b,'bag',{x:ps[0].x,y:ps[0].y}),null)});
test('ring slots hold independent rings and swaps are lossless',()=>{const g=make();for(const id of ['r1','r2','r3'])g.grantItem(item(id,{forceSlot:'ring'}));assert.equal(g.equip('r1','ring1').ok,true);assert.equal(g.equip('r2','ring2').ok,true);assert.equal(g.equip('r3','ring1').ok,true);assert.equal(g.state.gear.ring1.id,'r3');assert.equal(g.state.gear.ring2.id,'r2');assert.equal(g.get('r1').where,'bag');assert.equal(g.state.placements.length,1)});
test('wrong slot does not take a gear item or change inventory',()=>{const g=make();const a=item('wrong',{forceSlot:'chest'});g.grantItem(a);const before=g.snapshot();assert.equal(g.equip(a.id,'head').ok,false);assert.deepEqual(g.snapshot(),before)});
test('level gates gear equipment',()=>{const g=make({level:1});g.grantItem(item('a',{level:80}));assert.equal(g.equip('a').reason,'level')});
test('unequip respects full bag and never deletes gear',()=>{const g=make();const a=item('a',{forceSlot:'chest'});g.grantItem(a);g.equip('a');for(let x=0;x<60;x++)g.grantItem({...item('ring-'+x,{forceSlot:'ring'}),w:1,h:1},'bag');assert.equal(g.unequip('chest').reason,'full');assert.equal(g.state.gear.chest?.id,'a')});
test('fully occupied grid routes excess items to vault then recovery',()=>{const g=make();for(let i=0;i<141;i++)g.grantItem({...item(`fill${i}`),w:1,h:1});assert.equal(g.state.placements.filter(p=>p.container==='bag').length,60);assert.equal(g.state.placements.filter(p=>p.container==='stash').length,80);assert.equal(g.state.overflow.length,1)});
test('sort never loses or duplicates ids',()=>{const g=new Armory({seed:'sort',level:20});const before=few(g.state.placements);assert.equal(g.sort('bag').ok,true);assert.deepEqual(few(g.state.placements).sort(),before.sort())});
test('moving to occupied slot fails atomically',()=>{const g=make();g.grantItem({...item('a'),w:1,h:1});g.grantItem({...item('b'),w:1,h:1});const a=g.get('a').placement,b=g.get('b').placement;assert.equal(g.move('a','bag',{x:b.x,y:b.y}).ok,false);assert.equal(g.get('a').placement.x,a.x)});
test('reclaiming a locked item is forbidden',()=>{const g=make();g.grantItem(item('locked'));g.setLocked('locked',true);assert.equal(g.salvage('locked').reason,'locked');assert.equal(g.get('locked').item.id,'locked')});
test('salvage increases real resource records and cannot repeat',()=>{const g=make();g.grantItem(item('salvage',{forceRarity:'epic'}));const old=g.state.resources.scrap;assert.equal(g.salvage('salvage').ok,true);assert.ok(g.state.resources.scrap>old);assert.equal(g.salvage('salvage').ok,false)});
test('upgrade charges costs, improves stats, caps at eight and prevents negative resources',()=>{const g=make();g.grantItem(item('tempered'));g.state.resources={scrap:9999,essence:9999,starshard:9999};let old=g.get('tempered').item.stats;for(let i=0;i<8;i++){const r=g.upgrade('tempered');assert.ok(r.ok);let cur=g.get('tempered').item.stats;for(const k of Object.keys(old))assert.ok(cur[k]>old[k]);old=cur;}assert.equal(g.upgrade('tempered').reason,'maxed');assert.ok(Object.values(g.state.resources).every(v=>v>=0))});
test('claiming encounter produces canonical resource records with no duplicate awards',()=>{const g=make();const args={eventId:'boss:chapter-1:001',enemyId:'sablecantor',difficulty:3};const preview=g.previewEncounter(args);const coins=g.state.coins;const got=g.claimEncounter(args);assert.equal(got.ok,true);assert.deepEqual(got.equipment,preview.equipment);assert.equal(g.state.coins,coins+got.resources.coins);const state=g.snapshot();assert.equal(g.claimEncounter(args).reason,'already-claimed');assert.deepEqual(g.snapshot(),state)});
test('boss guarantees an epic-or-higher drop',()=>{const g=make();for(let i=0;i<25;i++){const r=g.previewEncounter({eventId:`boss-${i}`,enemyId:'sablecantor'});assert.ok(r.equipment.length>=2);assert.ok(['epic','legendary','mythic'].includes(r.equipment[0].rarity))}});
test('all creature profiles generate valid finite rewards',()=>{const g=make();for(const e of ENEMIES){const r=g.previewEncounter({eventId:e.id,enemyId:e.id});assert.equal(r.enemyId,e.id);assert.ok(r.resources.coins>0);assert.ok(r.equipment.length<=3);}});
test('stats use multi-set threshold bonuses without losing base item stats',()=>{const g=make();const selected=UNIQUES.filter(u=>u.set==='choir');for(let i=0;i<2;i++){const u=selected[i];const it=item(`set-${i}`,{forceSlot:u.slot,forceUnique:u.id,forceRarity:'legendary'});g.grantItem(it);g.equip(it.id)}assert.equal(g.setProgress()[0].count,2);assert.ok(g.stats().focus>=7+SETS.find(s=>s.id==='choir').bonuses[0].value)});
test('combat multipliers are numeric, shield responds to piercing and material',()=>{const g=make();let a=g.combatModifiers({enemyShielding:.8,terrainElement:'ember',attackElement:'ember',terrainResonance:.9});let b=g.combatModifiers({enemyShielding:.1,terrainElement:'ember',attackElement:'ember',terrainResonance:.9});assert.ok(b.damageFactor>a.damageFactor);for(const x of Object.values(a))if(typeof x==='number')assert.ok(Number.isFinite(x));});
test('valid snapshot roundtrips and rejects overlap, duplicate id and wrong version',()=>{const g=new Armory({seed:'roundtrip',level:16});g.claimEncounter({eventId:'once',enemyId:'cinderstag'});const snap=g.snapshot(),h=make();h.load(snap);assert.deepEqual(h.snapshot(),snap);assert.equal(h.claimEncounter({eventId:'once'}).reason,'already-claimed');assert.throws(()=>h.load({...snap,version:9}));let bad=structuredClone(snap);bad.placements.push({...bad.placements[0]});assert.throws(()=>h.load(bad));assert.deepEqual(h.snapshot(),snap)});
test('NG+ namespaces item and encounter ledger, optional carry is preserved',()=>{const g=make();const a=item('keeper');g.grantItem(a);g.claimEncounter({eventId:'same',enemyId:'cinderstag'});g.newTimeline('afterfire',{carry:a.id});assert.equal(g.state.timeline,'afterfire');assert.equal(g.state.placements.length,1);assert.match(g.state.placements[0].item.id,/afterfire/);assert.equal(g.claimEncounter({eventId:'same',enemyId:'cinderstag'}).ok,true)});
test('generate 1500 varied deterministic gear without invalid values',()=>{const slots=new Set(),names=new Set(),rarities=new Set();for(let i=0;i<1500;i++){const g=rollItem({seed:'variety',eventId:'sample'+i,level:1+i%80,region:REGIONS[i%8].id,elite:i%5===0,boss:i%19===0});slots.add(g.slot);names.add(g.name);rarities.add(g.rarity);assert.ok(g.w<=10&&g.h<=8);assert.ok(Object.values(g.stats).every(Number.isFinite));}assert.ok(slots.size>=11);assert.ok(names.size>=200);assert.ok(rarities.size>=4)});
test('unique abilities alter real world modifiers, not only tooltip text',()=>{
 const g=make(),ctx={attackElement:'aether',terrainElement:'aether',terrainResonance:.8,enemyShielding:.6,terrainShielding:.5,longRange:true};
 const before=g.combatModifiers(ctx);
 const u=item('starlight',{forceSlot:'mainhand',forceUnique:'u_bow',forceRarity:'legendary'});g.grantItem(u);g.equip(u.id);
 assert.ok(g.effects().some(x=>x.id==='falling-stars'&&x.magnitude===.15));
 const after=g.combatModifiers(ctx);assert.ok(after.shieldBroken>before.shieldBroken);assert.ok(after.damageFactor>before.damageFactor);
});
test('root armor, water crown and rooted boots change environmental defenses and grip',()=>{
 const g=make();const specs=[['root','chest','u_root'],['helm','head','u_helm'],['steps','feet','u_boots']];
 for(const [id,slot,forceUnique]of specs){const t=item(id,{forceSlot:slot,forceUnique,forceRarity:'legendary',level:20});g.grantItem(t);assert.equal(g.equip(id).ok,true)}
 const plain=g.combatModifiers({organicTerrain:false,waterTerrain:false,rootedTerrain:false});const special=g.combatModifiers({organicTerrain:true,waterTerrain:true,rootedTerrain:true});
 assert.ok(special.protection>plain.protection);assert.ok(special.guard>plain.guard);assert.ok(special.grip>plain.grip);assert.equal(special.patrolDetectionMultiplier,.92);
});
test('timed unique trigger fires on the fourth encounter without mutating battle owner',()=>{
 const g=make();const u=item('clock',{forceSlot:'relic',forceUnique:'u_clock',forceRarity:'legendary'});g.grantItem(u);g.equip(u.id);
 for(let n=1;n<=4;n++){const r=g.claimEncounter({eventId:`w${n}`,enemyId:'cinderstag'});assert.equal(r.triggeredEffects.length,n===4?1:0);}
});
test('timeline sigil implements an additional NG+ memory',()=>{
 const g=make();const u=item('memory',{forceSlot:'sigil',forceUnique:'u_sigil',forceRarity:'legendary'});g.grantItem(u);g.equip(u.id);g.claimEncounter({eventId:'chapter:end',enemyId:'glasschoir'});
 g.newTimeline('after-bell');assert.equal(g.state.legacyMemories.length,1);assert.equal(g.state.legacyMemories[0].name,'Glass Choir');
});
